package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

var fact, invFact []int64

func modPow(a, e int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return res
}

func comb(n, k int) int64 {
	if n < 0 || k < 0 || k > n {
		return 0
	}
	return fact[n] * invFact[k] % mod * invFact[n-k] % mod
}

// Number of ordered m-tuples with entries in [0, x-1] and sum q.
func boundedCompositions(m, x, q int) int64 {
	if q < 0 || q > m*(x-1) {
		return 0
	}
	if m == 0 {
		if q == 0 {
			return 1
		}
		return 0
	}

	limit := q / x
	if limit > m {
		limit = m
	}

	var res int64
	for j := 0; j <= limit; j++ {
		term := comb(m, j) * comb(q-j*x+m-1, m-1) % mod
		if j&1 == 0 {
			res += term
			if res >= mod {
				res -= mod
			}
		} else {
			res -= term
			if res < 0 {
				res += mod
			}
		}
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var p, s, r int
	fmt.Fscan(in, &p, &s, &r)

	if s == 0 {
		fmt.Println(modPow(int64(p), mod-2))
		return
	}

	maxN := s + p + 5
	fact = make([]int64, maxN)
	invFact = make([]int64, maxN)

	fact[0] = 1
	for i := 1; i < maxN; i++ {
		fact[i] = fact[i-1] * int64(i) % mod
	}
	invFact[maxN-1] = modPow(fact[maxN-1], mod-2)
	for i := maxN - 1; i > 0; i-- {
		invFact[i-1] = invFact[i] * int64(i) % mod
	}

	totalStates := comb(s-r+p-1, p-1)
	opponents := p - 1

	start := r
	minPossibleMaximum := (s + p - 1) / p
	if start < minPossibleMaximum {
		start = minPossibleMaximum
	}

	inverses := make([]int64, p+1)
	for i := 1; i <= p; i++ {
		inverses[i] = modPow(int64(i), mod-2)
	}

	var winningSum int64

	for x := start; x <= s; x++ {
		maxTiedOpponents := s/x - 1
		if maxTiedOpponents > opponents {
			maxTiedOpponents = opponents
		}

		for k := 0; k <= maxTiedOpponents; k++ {
			remainingPlayers := opponents - k
			remainingScore := s - (k+1)*x

			count := boundedCompositions(remainingPlayers, x, remainingScore)
			if count == 0 {
				continue
			}

			count = count * comb(opponents, k) % mod
			count = count * inverses[k+1] % mod

			winningSum += count
			if winningSum >= mod {
				winningSum -= mod
			}
		}
	}

	answer := winningSum * modPow(totalStates, mod-2) % mod
	fmt.Println(answer)
}

