import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

func modPow(a, e int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var p, s, r int
	fmt.Fscan(in, &p, &s, &r)

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if p == 1 || r > s/2 {
		fmt.Fprintln(out, 1)
		return
	}
	if r == 0 {
		fmt.Fprintln(out, modPow(int64(p), mod-2))
		return
	}

	maxN := s + p + 5
	fact := make([]int64, maxN)
	invFact := make([]int64, maxN)
	fact[0] = 1
	for i := 1; i < maxN; i++ {
		fact[i] = fact[i-1] * int64(i) % mod
	}
	invFact[maxN-1] = modPow(fact[maxN-1], mod-2)
	for i := maxN - 1; i > 0; i-- {
		invFact[i-1] = invFact[i] * int64(i) % mod
	}

	comb := func(n, k int) int64 {
		if n < 0 || k < 0 || k > n {
			return 0
		}
		return fact[n] * invFact[k] % mod * invFact[n-k] % mod
	}

	inv := make([]int64, p+1)
	inv[1] = 1
	for i := 2; i <= p; i++ {
		inv[i] = (mod - (mod/int64(i))*inv[mod%int64(i)]%mod) % mod
	}

	m := p - 1
	numerator := int64(0)

	for x := r; x <= s; x++ {
		n := s - x

		if x > n {
			numerator += comb(n+m-1, m-1)
			if numerator >= mod {
				numerator -= mod
			}
			continue
		}

		maxK := n / x
		if maxK > m-1 {
			maxK = m - 1
		}

		for k := 0; k <= maxK; k++ {
			l := m - k
			jMax := n/x - k
			if jMax > l {
				jMax = l
			}

			coefficient := int64(0)
			for j := 0; j <= jMax; j++ {
				t := n - (k+j)*x
				term := comb(l, j) * comb(t+l-1, l-1) % mod
				if j&1 == 0 {
					coefficient += term
					if coefficient >= mod {
						coefficient -= mod
					}
				} else {
					coefficient -= term
					if coefficient < 0 {
						coefficient += mod
					}
				}
			}

			waysToChooseTies := comb(m, k)
			contribution := waysToChooseTies * inv[k+1] % mod
			contribution = contribution * coefficient % mod
			numerator += contribution
			if numerator >= mod {
				numerator -= mod
			}
		}

		if n == m*x {
			numerator += inv[p]
			if numerator >= mod {
				numerator -= mod
			}
		}
	}

	denominator := comb(s-r+p-1, p-1)
	answer := numerator * modPow(denominator, mod-2) % mod
	fmt.Fprintln(out, answer)
}

